CREATE TABLE IF NOT EXISTS migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE school (id TEXT PRIMARY KEY CHECK(id='school'), name TEXT NOT NULL DEFAULT 'CLASO', timezone TEXT NOT NULL DEFAULT 'UTC', locale TEXT NOT NULL DEFAULT 'en' CHECK(locale IN ('en','ar')), version INTEGER NOT NULL DEFAULT 1);
INSERT INTO school(id) VALUES ('school');
CREATE TABLE roles (id TEXT PRIMARY KEY);
INSERT INTO roles VALUES ('admin'),('teacher'),('student');
CREATE TABLE permissions (id TEXT PRIMARY KEY, description TEXT NOT NULL);
INSERT INTO permissions VALUES ('school.manage','Manage school and academic structure'),('people.manage','Manage school accounts'),('class.manage','Manage assigned teaching work'),('assessment.submit','Submit enrolled class work'),('audit.read','Read school audit history');
CREATE TABLE role_permissions (role_id TEXT REFERENCES roles(id), permission_id TEXT REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
INSERT INTO role_permissions VALUES ('admin','school.manage'),('admin','people.manage'),('admin','class.manage'),('admin','audit.read'),('teacher','class.manage'),('student','assessment.submit');
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, role TEXT NOT NULL REFERENCES roles(id), password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), must_change_password INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_limits (key TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL);
CREATE TABLE academic_years (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','archived')), version INTEGER NOT NULL DEFAULT 1, CHECK(start_date < end_date));
CREATE UNIQUE INDEX one_active_year ON academic_years(status) WHERE status='active';
CREATE TABLE terms (id TEXT PRIMARY KEY, year_id TEXT NOT NULL REFERENCES academic_years(id), name TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(year_id,name), CHECK(start_date < end_date));
CREATE TABLE grades (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sections (id TEXT PRIMARY KEY, grade_id TEXT NOT NULL REFERENCES grades(id), name TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(grade_id,name));
CREATE TABLE tracks (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE subjects (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE classes (id TEXT PRIMARY KEY, name TEXT NOT NULL, year_id TEXT NOT NULL REFERENCES academic_years(id), term_id TEXT NOT NULL REFERENCES terms(id), section_id TEXT NOT NULL REFERENCES sections(id), track_id TEXT REFERENCES tracks(id), subject_id TEXT NOT NULL REFERENCES subjects(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), version INTEGER NOT NULL DEFAULT 1, UNIQUE(year_id,name));
CREATE TABLE teacher_assignments (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), teacher_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL DEFAULT 1, UNIQUE(class_id,teacher_id));
CREATE TABLE enrollments (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(class_id,student_id));
CREATE INDEX enrollments_student ON enrollments(student_id,class_id);
CREATE INDEX teacher_assignments_teacher ON teacher_assignments(teacher_id,class_id);
CREATE TABLE lessons (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE files (id TEXT PRIMARY KEY, original_name TEXT NOT NULL, storage_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, size INTEGER NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE resources (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', topic TEXT NOT NULL DEFAULT '', url TEXT, file_id TEXT REFERENCES files(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, CHECK(url IS NOT NULL OR file_id IS NOT NULL));
CREATE TABLE assignments (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), title TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', file_id TEXT REFERENCES files(id), open_at TEXT NOT NULL, due_at TEXT NOT NULL, max_score REAL NOT NULL CHECK(max_score > 0 AND max_score <= 10000), allow_late INTEGER NOT NULL DEFAULT 0 CHECK(allow_late IN (0,1)), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','complete')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, CHECK(open_at < due_at));
CREATE TABLE submissions (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL, file_id TEXT REFERENCES files(id), submitted_at TEXT NOT NULL, score REAL, feedback TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','graded','returned')), graded_by TEXT REFERENCES users(id), version INTEGER NOT NULL DEFAULT 1, UNIQUE(assignment_id,student_id));
CREATE TABLE question_banks (id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES subjects(id), title TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE questions (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES question_banks(id), type TEXT NOT NULL CHECK(type IN ('multiple_choice','true_false','short_answer','image','equation')), prompt TEXT NOT NULL, options TEXT NOT NULL DEFAULT '[]', correct_answer TEXT NOT NULL DEFAULT '', explanation TEXT NOT NULL DEFAULT '', topic TEXT NOT NULL DEFAULT '', difficulty TEXT NOT NULL DEFAULT 'medium' CHECK(difficulty IN ('easy','medium','hard')), tags TEXT NOT NULL DEFAULT '', file_id TEXT REFERENCES files(id), points REAL NOT NULL CHECK(points > 0 AND points <= 10000), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE exams (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), title TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', opens_at TEXT NOT NULL, closes_at TEXT NOT NULL, duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 1 AND 480), max_attempts INTEGER NOT NULL DEFAULT 1 CHECK(max_attempts BETWEEN 1 AND 10), randomize_questions INTEGER NOT NULL DEFAULT 0, randomize_options INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','scheduled','published','closed','results')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, CHECK(opens_at < closes_at));
CREATE TABLE exam_questions (id TEXT PRIMARY KEY, exam_id TEXT NOT NULL REFERENCES exams(id), source_id TEXT REFERENCES questions(id), position INTEGER NOT NULL, type TEXT NOT NULL, prompt TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, points REAL NOT NULL, file_id TEXT REFERENCES files(id), UNIQUE(exam_id,position));
CREATE TABLE attempts (id TEXT PRIMARY KEY, exam_id TEXT NOT NULL REFERENCES exams(id), student_id TEXT NOT NULL REFERENCES users(id), started_at TEXT NOT NULL, deadline TEXT NOT NULL, submitted_at TEXT, status TEXT NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','submitted','graded')), question_order TEXT NOT NULL, option_orders TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX one_live_attempt ON attempts(exam_id,student_id) WHERE status='in_progress';
CREATE INDEX attempts_student ON attempts(student_id,exam_id);
CREATE TABLE answers (attempt_id TEXT NOT NULL REFERENCES attempts(id), question_id TEXT NOT NULL REFERENCES exam_questions(id), value TEXT NOT NULL, score REAL, feedback TEXT NOT NULL DEFAULT '', PRIMARY KEY(attempt_id,question_id));
CREATE TABLE schedules (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 6), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, room TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, CHECK(starts_at < ends_at));
CREATE TABLE announcements (id TEXT PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL, audience_type TEXT NOT NULL CHECK(audience_type IN ('school','grade','section','track','class','user')), audience_id TEXT, publish_at TEXT NOT NULL, expires_at TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX notifications_user ON notifications(user_id,created_at);
CREATE TABLE messages (id TEXT PRIMARY KEY, sender_id TEXT NOT NULL REFERENCES users(id), recipient_id TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, content TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX messages_recipient ON messages(recipient_id,created_at);
CREATE TABLE imports (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), fingerprint TEXT NOT NULL UNIQUE, rows TEXT NOT NULL, expires_at TEXT NOT NULL, committed_at TEXT, result TEXT);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, context TEXT NOT NULL DEFAULT '{}', request_id TEXT, created_at TEXT NOT NULL);
CREATE INDEX audit_created ON audit_events(created_at);
CREATE INDEX resources_class ON resources(class_id,status);
CREATE INDEX assignments_class ON assignments(class_id,status,due_at);
CREATE INDEX exams_class ON exams(class_id,status,opens_at);
CREATE INDEX submissions_assignment ON submissions(assignment_id,status);
CREATE INDEX classes_year ON classes(year_id,term_id,status);
CREATE INDEX questions_bank ON questions(bank_id,topic);
CREATE INDEX announcements_publication ON announcements(status,publish_at);
CREATE INDEX users_role ON users(role,status);
